    [46] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "As a strong feeling of drowsiness came over me, I stopped up my ears. But the sound of the piano seemed to have already gotten into my veins. Every cell in my body reverberated along with it.",
