    },
    [47] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "With all my might, I stepped forward to a window and looked in. The unnatural sight before me sent a shiver down my spine--",
