    [48] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "Everyone in the hall was swaying and shaking as if possessed, with smiles of disturbing serenity on their faces.",
