    },
    [49] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "The people below the stage were like soulless puppets, eyes closed and wild with rejoicing. On the stage, Cyril held his eyes lightly closed as he played out the final requiem for them.",
      next = {50}
    },
    [50] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "My own consciousness became increasingly blurred under the spell of this infectious piano music. Even what I saw right in front of me started to distort along with the music.",
