    },
    [51] = {
      beijing = 1357,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "In the last moment before I lost consciousness, I saw the helicopter that had just flown me here spiral and fall.",
