  [420531] = {
    [1] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "It was Lucien's birthday. But unlike his previous birthdays, this one was even more special—",
      next = {2}
    },
    [2] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "In the morning, Lucien would be giving a presentation on a topic he had been researching for years.",
      next = {3}
    },
    [3] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "The subject of the speech was displayed in large font on the projector screen: On the Cognition of Emotions for Brain-Damaged Patients and the Intervention Strategies for Post-Trauma Emotion Identification.",
      next = {4}
    },
    [4] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "I sat inconspicuously at the very back of the conference hall, watching the academics walk in.",
      next = {5}
    },
    [5] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "I knew that Lucien had been working on this topic even before I first met him.",
      next = {6}
    },
    [6] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "I understood very little about this subject, but judging from the whispers of the viewers, it was a huge topic for neuroscientists, one that had not been resolved yet.",
      next = {7}
    },
    [7] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      ruchang = -1,
      sentence = "The suit-clad Lucien scanned the room from his place on the platform. His gaze landed on my general location for a few seconds, and then he walked up to the podium.",
      next = {8}
    },
    [8] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "Twenty years ago, the general public did not have much interest in the emotion cognition abilities of patients with Traumatic Brain Injury (TBI).",
      voice = 2,
      next = {9}
    },
    [9] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "Many thought these were but small hurdles the patients experienced during their treatment that was brought about by changes in their mental states.",
      voice = 2,
      next = {10}
    },
    [10] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "A study conducted in 2012 showed that there are 54 to 60 million TBI patients around the world every year, with 2.2 to 3.6 million of them suffering from medium-to-heavy brain damage.",
      voice = 2,
      next = {11}
    },
    [11] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "In recent years, as science has progressed, we have been able to monitor the changes in the physical stats of TBI patients through the use of advanced equipment.",
      voice = 2,
      next = {12}
    },
    [12] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "We have thus discovered that emotional changes—a cognitive function in traditional psychology—may occur due to physical changes in the brain.",
      voice = 2,
      next = {13}
    },
    [13] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      sentence = "And therefore, following this train of thought, we've further investigated the mechanism causing changes in the emotion cognition of TBI patients.",
      voice = 2,
      next = {14}
    },
    [14] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 275000,
      role2 = 202101,
      role3 = 202201,
      ruchang = 9,
      sentence = "According to the results of our study, we've come up with intervention strategies for the post-trauma emotion cognition of TBI patients.",
      voice = 2,
      next = {15}
    },
    [15] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "Lucien enunciates calmly, solemnly, as he goes from slide to slide.",
      next = {16}
    },
    [16] = {
      beijing = 1473,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "The audience is completely silent, mesmerized. All that's audible besides Lucien's voice is the rustling of paper.",
      next = {17}
    },
    [17] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 274000,
      role2 = 201105,
      role3 = 201201,
      role5 = 274404,
      ruchang = -1,
      sentence = "Patients with TBI can also become anxious as their conditions continue, and their anxiety may aggravate other cognitive impairments.",
      voice = 2,
      next = {18}
    },
    [18] = {
      beijing = 1473,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "19_Daily02",
      renming = "Lucien",
      renwu = "npc",
      role1 = 274000,
      role2 = 201105,
